<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A')
const filled=ref(true)
const selected=ref(0)
const state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const primary=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:[0,0,0,0,0,0])
const x=(i:number)=>40+i*48
const y=(v:number)=>170-v*1.4
const points=(values:number[])=>values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')
const lower=computed(()=>primary.value.map(v=>Math.max(v-15,0)))
const upper=computed(()=>primary.value.map(v=>Math.min(v+15,100)))
const area=computed(()=>upper.value.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ')+lower.value.map((_,j)=>{const i=5-j;return ` L${x(i)},${y(lower.value[i])}`}).join('')+' Z')
function reset(){dataset.value='A';filled.value=true;selected.value=0;state.value='ready'}
</script>
<template>
<section class="range-chart-demo" aria-label="Local range band example"><p>Synthetic monthly units. Band shows lower and upper sample bounds. These are not confidence intervals.</p><div class="range-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">Zero center</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label><input v-model="filled" type="checkbox">Show band fill</label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="range-legend"><span>Solid: Upper bound</span><span>Dashed: Lower bound</span></div><svg :key="dataset+'-'+filled" viewBox="0 0 320 210" role="img" aria-label="Synthetic monthly units, January to June, fixed scale 0 to 100. Band lies between lower and upper bounds; exact values are in the table below."><g v-for="tick in [0,25,50,75,100]" :key="tick"><line x1="36" x2="292" :y1="y(tick)" :y2="y(tick)" class="range-grid"/><text x="4" :y="y(tick)+4">{{ tick }}</text></g><text v-for="(label,i) in labels" :key="label" :x="x(i)" y="194" text-anchor="middle">{{ label }}</text><path v-if="filled" :d="area" class="range-fill"/><polyline :points="points(upper)" class="range-primary"/><polyline :points="points(lower)" class="range-secondary"/><circle v-for="(v,i) in upper" :key="i" :cx="x(i)" :cy="y(v)" :r="selected===i?5:3" class="range-dot"/></svg><div role="group" aria-label="Select month" class="range-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Lower {{ lower[selected] }}, Upper {{ upper[selected] }} units.</p><table class="range-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Lower</th><th scope="col">Upper</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ lower[i] }}</td><td>{{ upper[i] }}</td></tr></tbody></table></template><p v-else role="status" class="range-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.range-chart-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.range-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.range-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.range-chart-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.range-chart-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.range-chart-demo :is(button,select,input):focus-visible{outline:2px solid var(--vp-c-brand-1);outrange-offset:3px}.range-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.range-chart-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:range-chart-in .2s ease-out}.range-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.range-chart-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.range-primary,.range-secondary{fill:none;stroke:var(--vp-c-brand-1);stroke-width:2.5}.range-secondary{stroke-dasharray:5 4;stroke:var(--vp-c-text-2)}.range-fill{fill:var(--vp-c-brand-1);fill-opacity:.18;stroke:none}.range-dot{fill:var(--vp-c-brand-1);stroke:var(--vp-c-bg);stroke-width:1}.range-months{display:flex;gap:6px;flex-wrap:wrap}.range-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.range-data{display:table!important;width:100%;font-size:12px}.range-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.range-data :is(td,th){padding:6px 8px!important}.range-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes range-chart-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.range-chart-demo svg{animation:none}}
</style>
